 This example demonstrates interactive target selection by clicking on display coordinates.  #include &quot;lib-pid-otrack.h&quot; #include &lt;iostream&gt; using namespace DctotrackPID; // Simulate user clicking at display coordinates void handleUserClick(ObjectTrackerLib&amp; tracker, float click_x, float click_y) { printf(&quot;User clicked at (%.1f, %.1f)
&quot;, click_x, click_y); if (tracker.ai_obj_trk_set_by_coordinate(click_x, click_y)) { int selected_id = tracker.ai_obj_trk_get_target_id(); printf(&quot;Selected object ID: %d
&quot;, selected_id); DetectedObject target; if (tracker.ai_obj_trk_get_current_target(target)) { printf(&quot;Target at (%.1f, %.1f) with confidence %.2f
&quot;, target.x, target.y, target.confidence); } } else { printf(&quot;No object found near click position
&quot;); } } // Display available objects void showAvailableObjects(ObjectTrackerLib&amp; tracker) { auto ids = tracker.ai_obj_trk_get_available_ids(); printf(&quot;Available object IDs: &quot;); for (int id : ids) { printf(&quot;%d &quot;, id); } printf(&quot;
&quot;); } int main() { ObjectTrackerLib tracker( FrameResolution(640, 384), FrameResolution(1920, 1080) ); tracker.initializeWithConfig(&quot;interactive_app&quot;); tracker.ai_obj_trk_set_mode(TrackingMode::CENTROID); tracker.ai_obj_trk_enable(); while (running) { // Get detections std::vector&lt;DetectedObject&gt; detections = getDetections(); tracker.ai_obj_trk_update_detections(detections); // Show available objects showAvailableObjects(tracker); // Simulate user interaction // In a real app, this would come from mouse clicks or touch events if (userClickedScreen()) { float click_x, click_y; getUserClickCoordinates(click_x, click_y); handleUserClick(tracker, click_x, click_y); } // Calculate and apply tracking commands PanTiltCommand cmd = tracker.calculatePanTiltCommand(); if (cmd.valid) { controlPTZ(cmd.pan_delta, cmd.tilt_delta); } usleep(33000); } return 0; }

